# Optimized InDesign JSX Script: Transform Spreads to Single Pages

Here's a well-optimized JSX script that converts a multi-page spread document with master pages into a single-page document while preserving margins, layout, positioning, and master page references:

```jsx
// Optimized script to convert spreads to single pages while preserving all layout
// Features:
// - Maintains all master page references
// - Preserves exact positioning of all elements
// - Keeps original margins and layout
// - Handles both facing pages and single-page documents
// - Optimized for performance with large documents

#targetengine "session"

function main() {
    var doc = app.activeDocument;
    if (!doc) {
        alert("No document open");
        return;
    }

    app.scriptPreferences.enableRedraw = false; // Disable redraw for performance
    app.scriptPreferences.userInteractionLevel = UserInteractionLevels.NEVER_INTERACT;

    try {
        // Store original document properties
        var originalFacingPages = doc.documentPreferences.facingPages;
        var originalPageWidth = doc.documentPreferences.pageWidth;
        var originalPageHeight = doc.documentPreferences.pageHeight;
        var originalPageOrientation = doc.documentPreferences.pageOrientation;
        var originalMargins = {
            top: doc.marginPreferences.top,
            bottom: doc.marginPreferences.bottom,
            left: doc.marginPreferences.left,
            right: doc.marginPreferences.right,
            columnCount: doc.marginPreferences.columnCount,
            columnGap: doc.marginPreferences.columnGap
        };

        // Create a new document with single pages
        var newDoc = app.documents.add({
            name: doc.name + " (Single Pages)",
            facingPages: false,
            pageWidth: originalPageWidth,
            pageHeight: originalPageHeight,
            pageOrientation: originalPageOrientation,
            marginPreferences: originalMargins
        });

        // Copy all swatches, styles, and master pages
        copyDocumentResources(doc, newDoc);

        // Process each page in the original document
        for (var i = 0; i < doc.pages.length; i++) {
            var originalPage = doc.pages[i];
            var newPage = newDoc.pages.add();

            // Apply the same master page if one was applied
            if (originalPage.appliedMaster) {
                try {
                    newPage.appliedMaster = newDoc.masterSpreads[originalPage.appliedMaster.name];
                } catch (e) {
                    // Master might not exist in new doc (shouldn't happen with our copy)
                    $.writeln("Warning: Master page not found for page " + (i+1));
                }
            }

            // Copy all page items while maintaining position
            for (var j = originalPage.pageItems.length - 1; j >= 0; j--) {
                var originalItem = originalPage.pageItems[j];
                var newItem = originalItem.duplicate(newPage, ElementPlacement.PLACE_AT_BEGINNING);

                // Adjust position for spreads (if original was right-hand page)
                if (originalFacingPages && originalPage.side === PageSideOptions.RIGHT_HAND) {
                    newItem.geometryBounds = [
                        originalItem.geometryBounds[0] - originalPageWidth,
                        originalItem.geometryBounds[1],
                        originalItem.geometryBounds[2] - originalPageWidth,
                        originalItem.geometryBounds[3]
                    ];
                }
            }

            // Copy page margins and column settings
            newPage.marginPreferences.top = originalPage.marginPreferences.top;
            newPage.marginPreferences.bottom = originalPage.marginPreferences.bottom;
            newPage.marginPreferences.left = originalPage.marginPreferences.left;
            newPage.marginPreferences.right = originalPage.marginPreferences.right;
            newPage.marginPreferences.columnCount = originalPage.marginPreferences.columnCount;
            newPage.marginPreferences.columnGap = originalPage.marginPreferences.columnGap;
        }

        // Clean up and optimize
        newDoc.viewPreferences.overprintPreview = doc.viewPreferences.overprintPreview;
        newDoc.viewPreferences.rulerOrigin = doc.viewPreferences.rulerOrigin;

        // Show the result
        newDoc.window.visible = true;
        newDoc.activate();

    } catch (e) {
        alert("Error: " + e.message + "\nLine: " + e.line);
    } finally {
        app.scriptPreferences.enableRedraw = true;
        app.scriptPreferences.userInteractionLevel = UserInteractionLevels.INTERACT_WITH_ALL;
    }
}

function copyDocumentResources(sourceDoc, targetDoc) {
    // Copy colors
    for (var i = 0; i < sourceDoc.colors.length; i++) {
        try {
            sourceDoc.colors[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if color already exists
        }
    }

    // Copy swatches
    for (var i = 0; i < sourceDoc.swatches.length; i++) {
        try {
            sourceDoc.swatches[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if swatch already exists
        }
    }

    // Copy gradients
    for (var i = 0; i < sourceDoc.gradients.length; i++) {
        try {
            sourceDoc.gradients[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if gradient already exists
        }
    }

    // Copy paragraph styles
    for (var i = 0; i < sourceDoc.paragraphStyles.length; i++) {
        try {
            sourceDoc.paragraphStyles[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if style already exists
        }
    }

    // Copy character styles
    for (var i = 0; i < sourceDoc.characterStyles.length; i++) {
        try {
            sourceDoc.characterStyles[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if style already exists
        }
    }

    // Copy object styles
    for (var i = 0; i < sourceDoc.objectStyles.length; i++) {
        try {
            sourceDoc.objectStyles[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if style already exists
        }
    }

    // Copy table styles
    for (var i = 0; i < sourceDoc.tableStyles.length; i++) {
        try {
            sourceDoc.tableStyles[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if style already exists
        }
    }

    // Copy cell styles
    for (var i = 0; i < sourceDoc.cellStyles.length; i++) {
        try {
            sourceDoc.cellStyles[i].duplicate(targetDoc);
        } catch (e) {
            // Skip if style already exists
        }
    }

    // Copy master pages (need special handling for spreads)
    for (var i = 0; i < sourceDoc.masterSpreads.length; i++) {
        var originalMaster = sourceDoc.masterSpreads[i];

        // For master spreads, we'll convert them to single-page masters
        for (var j = 0; j < originalMaster.pages.length; j++) {
            var originalMasterPage = originalMaster.pages[j];
            var newMaster = targetDoc.masterSpreads.add({
                name: originalMaster.name + (originalMaster.pages.length > 1 ? " " + (j+1) : ""),
                facingPages: false
            });

            // Copy all items from the master page
            for (var k = originalMasterPage.pageItems.length - 1; k >= 0; k--) {
                originalMasterPage.pageItems[k].duplicate(newMaster.pages[0]);
            }

            // Copy master page margins
            newMaster.pages[0].marginPreferences.top = originalMasterPage.marginPreferences.top;
            newMaster.pages[0].marginPreferences.bottom = originalMasterPage.marginPreferences.bottom;
            newMaster.pages[0].marginPreferences.left = originalMasterPage.marginPreferences.left;
            newMaster.pages[0].marginPreferences.right = originalMasterPage.marginPreferences.right;
            newMaster.pages[0].marginPreferences.columnCount = originalMasterPage.marginPreferences.columnCount;
            newMaster.pages[0].marginPreferences.columnGap = originalMasterPage.marginPreferences.columnGap;
        }
    }
}

main();
```

## Key Features of This Script:

1. **Preservation of All Elements**:
   - Maintains exact positioning of all page items
   - Keeps all margins, columns, and guides
   - Preserves master page references

2. **Document Structure Handling**:
   - Converts spreads to single pages
   - Handles both facing pages and single-page documents
   - Adjusts positions for right-hand pages in spreads

3. **Resource Copying**:
   - Copies all colors, swatches, and gradients
   - Duplicates all paragraph, character, object, table, and cell styles
   - Properly converts master spreads to single-page masters

4. **Performance Optimizations**:
   - Disables screen redraw during processing
   - Processes items in reverse order for better performance
   - Includes error handling for robust execution

5. **Accurate Positioning**:
   - Correctly adjusts positions for items on right-hand pages in spreads
   - Maintains all geometric bounds of objects

To use this script, simply copy it into the Scripts panel in InDesign and run it on your document. The script will create a new document with all the same content but with each spread page converted to individual pages.

